{
  "url": "https://api.example.com/v1/startups/stats",
  "method": "GET",
  "description": "Retrieve aggregated statistics about startups in a given region.",
  "params": {
    "region": "string",          // e.g., "north-america", "europe-west", "asia-southeast"
    "min_funding_millions": "number",   // optional filter: minimum total funding in millions USD
    "max_age_months": "number",         // optional filter: maximum age of the startup in months
    "format": "json"            // optional: json (default), csv, xml
  },
  "headers": {
