    "https": "https://proxy.example.com:3128"
  },
  "stream": false,
  "verify": true
}
```

### How to use it

```python
import requests

def get_startup_stats(region, min_funding=None, max_age=None):
    url = "https://api.example.com/v1/startups/stats"
    headers = {"Accept": "application/json"}
    params = {"region": region, "format": "json"}

    # Optional filters
    if min_funding is not None:
        params["min_funding_millions"] = str(min_funding)
    if max_age is not None:
        params["max_age_months"] = str(max_age)

    # Bearer token auth
    token = "YOUR_ACCESS_TOKEN_HERE"
    headers["Authorization"] = f"Bearer {token}"

    response = requests.get(url, headers=headers, params=params, timeout=10)
    response.raise_for_status()
    return response.json()

# Example call
stats = get_startup_stats("north-america", min_funding=5, max_age=24)
print(stats)
```

> **Note:** Replace `"YOUR_ACCESS_TOKEN_HERE"` with a real token issued by your auth system.  
> If you’re using session cookies instead of bearer tokens, set `auth` to `None` and populate the `cookies` dict accordingly.

